# Enabling PIC for Shared Libraries (.so/.dll)

gcc -c -fPIC my_lib.c
gcc -shared -o libmy_lib.so my_lib.o
# -fPIC: Generates Position Independent Code
# -fPIE: Generates Position Independent Executable

# Core Mechanism: Indirection via Tables

// 1. Accessing Global Data (Read/Write)
// Uses Global Offset Table (GOT)
// Address calculated relative to current Instruction Pointer (RIP)

// Assembly concept:
// mov global_var@GOTPCREL(%rip), %rax
// mov (%rax), %ebx  (Load data via GOT pointer)

// 2. Calling External Functions
// Uses Procedure Linkage Table (PLT)

void call_external(void (*func)()) {
    // Jump to PLT entry
    // PLT redirects to GOT entry (which holds the resolved address)
    func();
}
// Internal calls use RIP-relative jumps directly.
